<?php require_once __DIR__.'/../config.php'; $u=require_admin(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check(); if(($_POST['action']??'')==='add'){ $s=$pdo->prepare('INSERT INTO schedules(driver_id,line_id,service_date,start_time,end_time,notes) VALUES(?,?,?,?,?,?)'); $s->execute([(int)$_POST['driver_id'],(int)$_POST['line_id'],$_POST['service_date'],$_POST['start_time'],$_POST['end_time'],trim($_POST['notes']??'')]); flash('Escala criada.'); } elseif(($_POST['action']??'')==='delete'){ $s=$pdo->prepare('DELETE FROM schedules WHERE id=?');$s->execute([(int)$_POST['id']]);flash('Escala removida.');} redirect('schedules.php');}
$drivers=$pdo->query("SELECT id,name FROM users WHERE role='driver' AND active=1 ORDER BY name")->fetchAll(); $lines=$pdo->query("SELECT id,code,name FROM lines WHERE active=1 ORDER BY code")->fetchAll(); $rows=$pdo->query("SELECT s.*,u.name driver,l.code,l.name line_name FROM schedules s JOIN users u ON u.id=s.driver_id JOIN lines l ON l.id=s.line_id ORDER BY s.service_date DESC,s.start_time DESC")->fetchAll(); layout_start('Escalas',$u); ?>
<div class="page-head"><div><h1>Escalas</h1><p class="muted">Atribui uma linha, horário e data a cada motorista.</p></div></div><section class="card"><h2>Nova escala</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><label>Motorista<select name="driver_id" required><?php foreach($drivers as $d): ?><option value="<?=$d['id']?>"><?=e($d['name'])?></option><?php endforeach; ?></select></label><label>Linha<select name="line_id" required><?php foreach($lines as $l): ?><option value="<?=$l['id']?>"><?=$l['code']?> — <?=e($l['name'])?></option><?php endforeach; ?></select></label><label>Data<input type="date" name="service_date" value="<?=date('Y-m-d')?>" required></label><label>Início<input type="time" name="start_time" value="06:00" required></label><label>Fim<input type="time" name="end_time" value="14:00" required></label><label class="wide">Notas<input name="notes" placeholder="Opcional"></label><div class="wide"><button class="btn primary">Criar escala</button></div></form></section>
<section class="card"><h2>Escalas registadas</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Motorista</th><th>Linha</th><th>Horário</th><th>Estado</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=date('d/m/Y',strtotime($r['service_date']))?></td><td><?=e($r['driver'])?></td><td><strong><?=$r['code']?></strong> — <?=e($r['line_name'])?></td><td><?=e($r['start_time'])?>–<?=e($r['end_time'])?></td><td><span class="status <?= $r['confirmed']?'ok':'pending'?>"><?= $r['confirmed']?'Confirmada':'Por confirmar'?></span></td><td><form method="post" onsubmit="return confirm('Remover esta escala?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="linkbtn danger">Remover</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
<?php layout_end(); ?>
